def bres(a,b):
    (r1,c1),(r2,c2)=a,b
    dr,dc=r2-r1,c2-c1
    if abs(dr)==abs(dc):
        step=(1 if dr>0 else -1 if dr<0 else 0, 1 if dc>0 else -1 if dc<0 else 0)
        return [(r1+k*step[0],c1+k*step[1]) for k in range(max(abs(dr),abs(dc))+1)]
    elif abs(dr)==0 or abs(dc)==0:
        return [(r,c) for r,c in zip(range(r1,r2+1),range(c1,c2+1))]
    return None
