def f(g):
    H,W=len(g),len(g[0])
    bg=max(set(x for r in g for x in r), key=lambda v: sum(r.count(v) for r in g))
    cells=[(i,j,g[i][j]) for i in range(H) for j in range(W) if g[i][j]!=bg]
    out=[[bg]*W for _ in range(H)]
    for i,j,v in cells: out[i][j]=v
    dirs=[(1,1),(1,-1),(-1,1),(-1,-1)]
    blocked=set()
    # mark pairs on same diagonal
    for (i,j,v) in cells:
        for di,dj in dirs:
            ii,jj=i+di,j+dj
            while 0<=ii<H and 0<=jj<W and g[ii][jj]==bg:
                if out[ii][jj]!=bg: blocked.add((ii,jj))
                ii+=di; jj+=dj
    for (i,j,v) in cells:
        for di,dj in dirs:
            ii,jj=i+di,j+dj
            while 0<=ii<H and 0<=jj<W and out[ii][jj]==bg and (ii,jj) not in blocked:
                out[ii][jj]=v; ii+=di; jj+=dj
