        else:       # same main-diag: fill between parametrize by row
            for kk in range(min(a[0],b[0])+1,max(a[0],b[0])):
                ii=kk; jj=a[1]+(kk-a[0])
                paint(ii,jj,c)
    # emission: colored cell c emits along perpendicular diagonal iff >=2 other-colored cells
    # of OTHER color bracket it strictly on one line
    for i in range(H):
        for j in range(W):
            if g[i][j]==bg: continue
            c=g[i][j]; s=i+j; dd=i-j
