            if len(os_)>=2 and min(p[0] for p in os_)<i<max(p[0] for p in os_):
                for dx,dy in ((1,1),(-1,-1)):
                    for t in range(1,H+W):
                        ii,jj=i+dx*t,j+dy*t
                        if not(0<=ii<H and 0<=jj<W): break
                        if g[ii][jj]!=bg: break
                        out[ii][jj]=c
            if len(od_)>=2 and min(p[0] for p in od_)<i<max(p[0] for p in od_):
                for dx,dy in ((1,-1),(-1,1)):
